const info = await getImageInfo(filePath).catch(() => ({ width: 0, height: 0 }))
let imageBottom = height
if (info.width && info.height) {
  const scale = Math.min(width / info.width, height / info.height)
  const dw = info.width * scale
  const dh = info.height * scale
  const dx = (width - dw) / 2
  const dy = (height - dh) / 2
  imageBottom = dy + dh
  ctx.drawImage(filePath, dx, dy, dw, dh)
} else {
  ctx.drawImage(filePath, 0, 0, width, height)
}
